/*
 * Fixed guest bases for Alter Echo's runtime-loaded modules.
 *
 * The table itself (module_layout.c) is generated by tools/build_modules.py
 * from the modules extracted off the disc; module_loader.c uses it to move
 * each module the game loads to the base its code was translated at.
 */
#ifndef AE_MODULE_LAYOUT_H
#define AE_MODULE_LAYOUT_H

#include <stdint.h>

typedef struct {
    const char     *name;      /* the DLL's own name, from its export directory */
    uint32_t        base;      /* effective base: RVA r lives at base + r */
    uint32_t        rawptr0;   /* first section's file offset (the loader's start) */
    uint32_t        packed;    /* bytes the loader reads: the sections' raw sizes */
    uint32_t        nsites;
    const uint32_t *sites;     /* HIGHLOW sites, offsets from base + rawptr0 */
} AeModule;

extern const AeModule g_ae_modules[];
extern const unsigned g_ae_module_count;
extern const uint32_t g_ae_module_region;
extern const uint32_t g_ae_module_span;

#endif
